3	type SectionVariant = "light" | "dark" | "navy" | "gradient" | "muted";
4	
5	const variantStyles: Record<SectionVariant, string> = {
6	  light: "bg-background text-foreground",
7	  dark: "bg-brand-navy text-white",
8	  navy: "bg-brand-navy-deep text-white",
9	  gradient: "gradient-cyan text-white",
10	  muted: "bg-muted text-foreground",
11	};
12	
13	export function SectionWrapper({
14	  variant = "light",
15	  className,
16	  children,
17	  id,
18	}: {
19	  variant?: SectionVariant;
20	  className?: string;
21	  children: React.ReactNode;
22	  id?: string;
23	}) {
24	  return (
25	    <section id={id} className={cn(variantStyles[variant], "py-16 md:py-24", className)}>
26	      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">{children}</div>
27	    </section>
28	  );
29	}
