import Image from 'next/image';
import Link from 'next/link';
import styles from './mission-hero.module.css';

const STAT_BADGES = [
  {
    icon: '/images/webflow/Layer_1-3.svg',
    label: 'White-Label by Default',
  },
  {
    icon: '/images/webflow/Layer_1-25.svg',
    label: 'Senior-Level Team',
  },
  {
    icon: '/images/webflow/Layer_1-22.svg',
    label: 'Structured Delivery',
  },
  {
    icon: '/images/webflow/Layer_1-24.svg',
    label: 'Agency-First Workflows',
  },
] as const;

export function MissionHero() {
  return (
    <section className={styles['section']}>
      <div className={styles['container']}>
        <div className={styles['inner']}>
          {/* Badge */}
          <div className={styles['badge']}>
            <span className={styles['badgeText']}>Our Mission</span>
          </div>

          {/* Heading */}
          <h1 className={styles['heading']}>
            The White-Label Delivery Partner Agencies Can Build On
          </h1>

          {/* Subtitle */}
          <p className={styles['subtitle']}>
            Boldteq operates as your behind-the-scenes production team—delivering
            senior-level design and development under your brand, with structure,
            speed, and reliability.
          </p>

          {/* Stat badges grid */}
          <div className={styles['badgeGrid']}>
            {STAT_BADGES.map((badge) => (
              <div key={badge.label} className={styles['statBadge']}>
                <Image
                  src={badge.icon}
                  alt={badge.label}
                  width={24}
                  height={24}
                  className={styles['statIcon']}
                  loading="eager"
                />
                <span className={styles['statLabel']}>{badge.label}</span>
              </div>
            ))}
          </div>

          {/* CTA buttons */}
          <div className={styles['ctaRow']}>
            <Link href="/book-a-demo" className={styles['ctaPrimary']}>
              Book a Demo
            </Link>
            <Link href="/contact" className={styles['ctaSecondary']}>
              Talk to Our Team
            </Link>
          </div>
        </div>

        {/* 2-column navy content grid */}
        <div className={styles['contentGrid']}>
          <div className={styles['contentCol']}>
            <h2 className={styles['contentHeading']}>
              To help digital agencies scale faster without hiring pressure or
              delivery chaos.
            </h2>
            <p className={styles['contentPara']}>
              Most agencies hit a ceiling not because they lack clients, but
              because they lack a reliable delivery system. Taking on more work
              means hiring more people, and hiring means contracts, onboarding,
              management overhead, and unpredictable quality. Boldteq exists to
              remove that ceiling entirely.
            </p>
          </div>

          <div className={styles['contentCol']}>
            <h2 className={styles['contentHeading']}>Why We Built Boldteq</h2>
            <p className={styles['contentPara']}>
              We built Boldteq because we saw agencies turning down profitable
              work not for lack of demand, but for lack of a trusted team to
              execute it. The freelance market is fragmented, quality is
              inconsistent, and building in-house teams is expensive and slow.
            </p>
            <p className={styles['contentPara']}>
              There had to be a better way—a model where agencies could tap into
              a dedicated, white-label delivery partner with the structure and
              standards of an in-house team, without the overhead. That&apos;s
              exactly what Boldteq is.
            </p>
          </div>
        </div>
      </div>
    </section>
  );
}

/* ============================================================
   MISSION HERO — mission-hero.module.css
   ============================================================ */

.section {
  background-color: #fff;
  background-image: url('/images/webflow/hero-background-1.png'),
    linear-gradient(180deg, #019ae614 0%, #019ae600 100%);
  background-position: 50% 100%, 0 0;
  background-repeat: no-repeat, repeat;
  background-size: cover, auto;
  padding-top: 4rem;
  padding-bottom: 0;
}

.container {
  max-width: 80rem;
  margin-left: auto;
  margin-right: auto;
  padding-left: 2rem;
  padding-right: 2rem;
}

.inner {
  text-align: center;
  max-width: 70rem;
  margin-left: auto;
  margin-right: auto;
  padding-bottom: 3rem;
}

/* ── Badge ── */
.badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background-color: rgba(33, 207, 255, 0.1);
  border: 1px solid rgba(33, 207, 255, 0.3);
  border-radius: 999px;
  padding: 6px 18px;
  margin-bottom: 1.5rem;
}

.badgeText {
  background: linear-gradient(90deg, #21cfff, #019ae6);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
  letter-spacing: 0.01em;
}

/* ── Heading ── */
.heading {
  color: #092245;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 48px;
  font-weight: 700;
  line-height: 1.2;
  margin-top: 0;
  margin-bottom: 1.25rem;
}

/* ── Subtitle ── */
.subtitle {
  color: #2b2b2b;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 28px;
  max-width: 52rem;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: 2.5rem;
}

/* ── Stat badges ── */
.badgeGrid {
  display: grid;
  grid-template-columns: repeat(4, auto);
  gap: 12px;
  justify-content: center;
  margin-bottom: 2.5rem;
}

.statBadge {
  display: flex;
  align-items: center;
  gap: 10px;
  background-color: #fff;
  border-radius: 10px;
  padding: 13px 20px;
